<template>
  <div v-if="!admin" class="login-shell">
    <div class="login-panel"><div class="eyebrow">WE BANK · OPERATIONS</div><h1>银行运营管理后台</h1><p>请选择演示岗位进入受控运营工作区</p>
      <div class="account-list"><button v-for="item in demoAccounts" :key="item.login_name" class="account" @click="enter(item.login_name)"><span class="avatar">{{ item.display_name.slice(0,1) }}</span><span><b>{{ item.display_name }}</b><small>{{ item.login_name }} · {{ item.role }}</small></span><span class="arrow">→</span></button></div>
      <div v-if="error" class="error">{{ error }}</div>
      <div class="login-note">演示账号由后端签发会话，权限、机构范围和审批规则真实校验。</div>
    </div>
  </div>
  <div v-else class="console">
    <header class="topbar"><div class="brand"><span class="mark">银</span><div><b>银行运营中心</b><small>AI Banking Agent · Control Room</small></div></div><div class="identity"><span>{{ admin.display_name }}</span><el-tag size="small" effect="dark">{{ admin.organization_name }}</el-tag><el-button link @click="logout">退出</el-button></div></header>
    <div class="workspace"><aside class="nav"><div class="scope"><span>当前岗位</span><b>{{ admin.roles.join(' / ') }}</b><small>{{ admin.data_scope }} 数据范围</small></div><button v-for="tab in tabs" :key="tab.key" :class="{active: view===tab.key}" @click="view=tab.key"><span>{{ tab.icon }}</span>{{ tab.label }}<i v-if="tab.badge">{{ tab.badge }}</i></button><div class="nav-foot">会话保护中<br><span>最近刷新 {{ refreshed }}</span></div></aside>
      <main class="main"><div class="page-head"><div><div class="crumb">运营后台 / {{ currentLabel }}</div><h2>{{ currentLabel }}</h2></div><el-button :loading="loading" @click="refresh">↻ 刷新数据</el-button></div>
        <section v-if="view==='dashboard'" class="grid"><div class="metrics"><article v-for="metric in metrics" :key="metric.label" class="metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></div><div class="wide panel"><div class="panel-head"><b>服务与模型状态</b><el-tag type="success">实时</el-tag></div><div class="services"><div v-for="(state,name) in data.services" :key="name"><span class="dot" :class="state==='online'?'ok':'warn'"></span>{{ serviceLabel(name) }}<b>{{ state }}</b></div></div><div class="hash">审计链：{{ data.audit_chain?.valid ? '完整' : '需检查' }} · 已校验 {{ data.audit_chain?.checked || 0 }} 条</div></div><div class="panel"><div class="panel-head"><b>风险分布</b><span class="muted">机构范围内</span></div><div class="risk-bars"><div v-for="(count,key) in data.risks" :key="key"><span>{{ key }}</span><i><em :style="{width:`${Math.min(100,count*25)}%`}"></em></i><b>{{ count }}</b></div></div></div><div class="panel"><div class="panel-head"><b>待处理队列</b></div><div class="queue"><div><strong>{{ data.open_reviews || 0 }}</strong><span>人工接管</span></div><div><strong>{{ data.pending_approvals || 0 }}</strong><span>待审批</span></div></div></div></section>
        <section v-else-if="view==='reviews'" class="panel table-panel"><div class="panel-head"><b>人工接管队列</b><span class="muted">按机构范围隔离</span></div><el-table :data="reviewItems" stripe><el-table-column prop="summary" label="任务" min-width="250"/><el-table-column prop="reason_code" label="原因"/><el-table-column prop="customer_masked" label="客户"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="110"><template #default="scope"><el-button v-if="scope.row.status==='open'" type="primary" link @click="claim(scope.row.id)">认领</el-button><span v-else class="muted">{{ scope.row.claimed_by }}</span></template></el-table-column></el-table></section>
        <section v-else-if="view==='risks'" class="panel table-panel"><div class="panel-head"><b>风险事件中心</b><el-tag type="danger">{{ riskItems.length }} 条</el-tag></div><el-table :data="riskItems" stripe><el-table-column prop="title" label="事件" min-width="240"/><el-table-column prop="event_type" label="类型"/><el-table-column prop="severity" label="等级"><template #default="s"><el-tag :type="s.row.severity==='high'?'danger':'warning'">{{ s.row.severity }}</el-tag></template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="description" label="证据" min-width="280"/></el-table></section>
        <section v-else-if="view==='approvals'" class="panel table-panel"><div class="panel-head"><b>双人复核审批</b><span class="muted">发起人与复核人必须分离</span></div><el-table :data="approvalItems" stripe><el-table-column prop="request_type" label="申请类型"/><el-table-column prop="requester_id" label="经办人"/><el-table-column prop="status" label="状态"/><el-table-column prop="reason" label="理由" min-width="280"/><el-table-column label="操作" width="150"><template #default="scope"><div v-if="scope.row.status==='PENDING' && canApprove"><el-button type="success" link @click="decide(scope.row.id,true)">批准</el-button><el-button type="danger" link @click="decide(scope.row.id,false)">拒绝</el-button></div></template></el-table-column></el-table></section>
        <section v-else class="panel table-panel"><div class="panel-head"><b>管理员审计</b><el-button link @click="verify">校验完整性</el-button></div><div v-if="auditState" class="audit-banner" :class="{bad:!auditState.valid}">{{ auditState.valid ? `链路完整 · 已校验 ${auditState.checked} 条` : `链路断点：第 ${auditState.broken_at} 条` }}</div><el-table :data="auditItems" stripe><el-table-column prop="ts" label="时间" width="190"/><el-table-column prop="action" label="动作"/><el-table-column prop="admin_id" label="管理员"/><el-table-column prop="risk_level" label="风险"/><el-table-column prop="outcome" label="结果"/></el-table></section>
      </main></div>
  </div>
</template>
<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { accounts, login, me, dashboard, reviews, claimReview, risks, approvals, decideApproval, audit, verifyAudit } from './api'
const admin=ref(null), demoAccounts=ref([]), error=ref(''), loading=ref(false), view=ref('dashboard'), data=ref({}), reviewItems=ref([]), riskItems=ref([]), approvalItems=ref([]), auditItems=ref([]), auditState=ref(null), refreshed=ref('--')
let timer
const tabs=computed(()=>[{key:'dashboard',label:'运营看板',icon:'◈'},{key:'reviews',label:'人工接管',icon:'◎',badge:data.value.open_reviews},{key:'risks',label:'风险事件',icon:'△',badge:riskItems.value.length},{key:'approvals',label:'审批中心',icon:'✓',badge:data.value.pending_approvals},{key:'audit',label:'审计与权限',icon:'⌘'}].filter(x=>x.key==='dashboard'||x.key==='audit'||admin.value?.permissions?.some(p=>p.startsWith(x.key==='reviews'?'human_reviews':x.key==='risks'?'risk_events':x.key==='approvals'?'approvals':'dashboard'))))
const currentLabel=computed(()=>tabs.value.find(x=>x.key===view.value)?.label||'运营看板'), canApprove=computed(()=>admin.value?.permissions?.includes('approvals.decide')), metrics=computed(()=>[{label:'任务总量',value:Object.values(data.value.tasks||{}).reduce((a,b)=>a+b,0),note:'当前机构范围'},{label:'风险事件',value:Object.values(data.value.risks||{}).reduce((a,b)=>a+b,0),note:'需持续关注'},{label:'人工接管',value:data.value.open_reviews||0,note:'等待处理'},{label:'待审批',value:data.value.pending_approvals||0,note:'双人复核'}])
const serviceLabel=k=>({api:'API 服务',database:'业务数据库',ollama:'本地 Ollama'}[k]||k)
async function enter(name){error.value='';try{const r=await login(name);localStorage.setItem('bank-admin-token',r.token);admin.value=await me();await refresh()}catch(e){error.value=e.response?.data?.detail||e.message}}
function logout(){localStorage.removeItem('bank-admin-token');admin.value=null}
async function refresh(){if(!admin.value)return;loading.value=true;try{data.value=await dashboard();if(admin.value.permissions.includes('human_reviews.read'))reviewItems.value=(await reviews()).items;if(admin.value.permissions.includes('risk_events.read'))riskItems.value=(await risks()).items;if(admin.value.permissions.includes('approvals.read'))approvalItems.value=(await approvals()).items;if(admin.value.permissions.includes('audit.read'))auditItems.value=(await audit()).items;refreshed.value=new Date().toLocaleTimeString()}catch(e){if(e.response?.status===401)logout()}finally{loading.value=false}}
async function claim(id){await claimReview(id);await refresh()}
async function decide(id,approved){await decideApproval(id,{approved,reason:approved?'复核通过':'风险原因不充分'});await refresh()}
async function verify(){auditState.value=await verifyAudit()}
onMounted(async()=>{demoAccounts.value=(await accounts()).accounts;const token=localStorage.getItem('bank-admin-token');if(token)try{admin.value=await me();await refresh()}catch(e){logout()};timer=setInterval(refresh,10000)})
onUnmounted(()=>clearInterval(timer))
</script>
<style scoped src="./styles.css"></style>
